fns.compressFallback:
function compressFallback(agent) {
  const keepTail = keepTailSize(agent.provider, agent.history.length)
  const split = splitHistory(agent.history, keepTail, tailBudgetTokens(agent.provider))
  if (!split) return false
  const tailMessages = agent.history.length - split.tailStart
  applyCompression(agent, split.headEnd, split.tailStart, FALLBACK_NOTE)
  // Fallback completion info (D-C2): mode marks the deterministic-truncation path — the panel
  // shows the degradation note ("truncated to N messages") ONLY after 3 consecutive failures.
  agent._lastCompressInfo = { mode: "fallback", tailMessages }
  return true
}

fns.compressIfNeeded:
async function compressIfNeeded(agent, threshold, callbacks, extras = {}, signal) {
  const history = agent.history
  // 单源（§6.16.4）：total / overhead 与 stats 面同一函数（既有内联式改调 contextUsage，判定语义零改）
  const usage = contextUsage(agent, extras)
  const tokens = usage.total
  const overhead = usage.overhead
  if (!extras.force && tokens <= threshold) return false

  const keepTail = keepTailSize(agent.provider, history.length)
  const split = splitHistory(history, keepTail, tailBudgetTokens(agent.provider))
  if (!split) {
    // History is too short (≤KEEP_HEAD+keepTail+1 messages) to find a middle section, but tokens exceed threshold — typically a single giant message
    // (large paste / huge injection). When summarization has no room, degrade to deterministic shrinking to ensure context always reduces
    return shrinkOversized(agent)
  }

  const middle = history.slice(split.headEnd, split.tailStart)

  // Compression request form v2/v3 (§6.14 / D-CC20): continuation — same system + same tools declaration (the turn's own
  // array) + the middle's verbatim messages + one tail instruction. 首现即复用回合所建前缀 ⟺ 带 tools 声明（无 tool_choice）
  // 且 `reasoning_effort` 与回合侧同值——v2 探针复测：8 格 84–98%（读数详表见批次档 §5）；不带 tools / 带 tool_choice:"none" / effort 异值 ⇒ 首现 0%（自建项复跑例外）；无 extras.tools ⇒ 不发 tools。
  // ⚠️ **不带 `tool_choice`**（设计 §6.14 备选② · 预注册判定规则「S3 <0.9 且 S4 ≥0.9 ⇒ 采纳 v2 减 tool_choice」启用——实测该参数使服务端丢弃 tools 区 ⇒ 首现命中 0%）。
  // ⚠️ v3（父侧 2026-09-18 裁定）：**随带与回合请求同源的 `reasoning_effort`**——下行不再覆盖 `agent.provider.reasoningEffort`（回合调用 `chat(agent.provider, …)` 同字段；
  // 不硬编码、未配置 ⇒ 缺省同修前。实证：deepseek 同值 95.69% / 异值首现 0%；族差/窗差：百炼 qwen 另有 `enable_thinking` 派生差、autoThink 的 turn 0 有改写窗口——登记见批次档 §5 上抛）。
  // Silent by design (D11): no onToken/onReasoning — the compaction process must not stream to the frontend.
  // signal propagates user cancellation (Ctrl+C) to the in-flight summary call.
  // Compression visibility (CONTEXT-COMPACTION.md §6.8 D-C1/D-C2): the frontend learns the compression
  // STARTED right before the summary LLM call ("Compressing context… / summarizing N messages" panel) — only
  // the lifecycle is surfaced, never the summary body. N = the number of history messages being summarized.
  callbacks?.onCompressStart?.({ messages: middle.length })
  const startedAt = performance.now()
  // F-CC2 焦点块（§6.16.2）：仅模型主动面携带——追加在**指令末条尾段**（`SUMMARIZE_PROMPT` 文本零改，
  // 只追加焦点块；无 focus ⇒ 请求体逐字节同修前——compress-form.test.mjs 零回归）。
  const messages = buildCompressMessages(history, split.tailStart, extras?.systemPrompt, SUMMARIZE_PROMPT)
  if (extras.focus) {
    const last = messages.at(-1)
    messages[messages.length - 1] = { ...last, content: last.content + focusBlock(String(extras.focus), anchorText(agent)) }
  }
  const summary = await chat({ ...agent.provider, thinking: null }, {
    messages,
    tools: extras?.tools,
    signal,
    // TRACES.md §6.1 D-TR4：轨迹元数据增补——kind=compress（上下文构建面——agent 元数据透出；
    // depth 经 extras.traceDepth——agent.mjs 主作用域传入——compress 调用点补齐）
    logCtx: {
      stage: "compress", child: agent._logId, kind: "compress",
      role: agent._role ?? null, depth: extras?.traceDepth ?? null,
      session: agent._sessionStart ?? null, cwd: agent.cwd,
      traces: agent.config?.traces?.enabled !== false,
    },
  })

  // Blank-summary guard (§6.14 退化面 3): a blank summary would land in applyCompression as
  // "middle dropped + empty note" and still count as success — throw into the failure chain instead.
  if (!summary.content?.trim()) throw new Error("compaction summary is empty")

  applyCompression(agent, split.headEnd, split.tailStart, COMPACTION_PREFIX + summary.content)

  // Completion info for the compression panel (D-C2): tokens freed = the pre-compression prompt
  // estimate (`tokens` — the value that tripped the threshold, incl. system/tools overhead on the
  // pure-estimation path) minus the post-compression estimate on the same basis. Elapsed = the
  // summary call + splice duration. agent.mjs forwards this to onCompress unchanged.
  agent._lastCompressInfo = {
    mode: "summary",
    tokensFreed: Math.max(0, Math.round(tokens - (estimateTokens(agent.history) + overhead))),
    elapsedMs: performance.now() - startedAt,
  }
  return true
}

fns.estimateTokens:
function estimateTokens(messages) {
  let tokens = 0
  for (const m of messages) {
    if (typeof m.content === "string") tokens += estimateText(m.content)
    else if (Array.isArray(m.content)) {
      for (const part of m.content) {
        if (part.type === "text") tokens += estimateText(part.text)
        else if (part.type === "image_url") tokens += IMAGE_TOKEN_ESTIMATE
      }
    }
    if (typeof m.reasoning_content === "string") tokens += estimateText(m.reasoning_content)
    for (const tc of m.tool_calls ?? []) {
      tokens += estimateText(tc.function?.name ?? "") + estimateText(tc.function?.arguments ?? "")
    }
  }
  return tokens
}

fns.isAssistantEchoPair:
function isAssistantEchoPair(prev, next) {
  return prev?.role === "assistant"
    && next?.role === "assistant"
    && !prev.reasoning_content
    && !(Array.isArray(prev.tool_calls) && prev.tool_calls.length > 0)
}

fns.mergeAdjacentAssistantEchoes:
function mergeAdjacentAssistantEchoes(history) {
  if (!Array.isArray(history)) return history
  let src = history
  for (;;) {
    let changed = false
    const next = []
    for (let i = 0; i < src.length; i++) {
      if (i + 1 < src.length && isAssistantEchoPair(src[i], src[i + 1])) {
        next.push({ ...src[i + 1], content: absorbEchoContent(src[i].content, src[i + 1].content) })
        i += 1
        changed = true
      } else {
        next.push(src[i])
      }
    }
    if (!changed) return src === history ? history : src
    src = next
  }
}

fns.pruneStaleToolOutputs:
function pruneStaleToolOutputs(agent) {
  const history = agent.history
  const stale = collectStaleToolOutputs(history, agent.provider)
  const counts = {
    pruned: stale.indexes.length,
    freed: stale.tokens,
    candidates: stale.candidates,
    tailKept: stale.tailKept,
    belowMin: stale.belowMin,
  }
  if (counts.pruned === 0) return counts
  for (const i of stale.indexes) {
    const m = history[i]
    // 多模态 tool 结果（content 数组）整体替换为 stub ⇒ 图像 part 丢弃（不可再取——prune 是删；回执只给重跑路径）
    const chars = typeof m.content === "string" ? m.content.length : JSON.stringify(m.content ?? "").length
    history[i] = { ...m, content: pruneStub(chars) }
  }
  agent._lastPromptTokens = null
  agent._usageAtLen = null
  return counts
}

fns.pushReal:
function pushReal(agent, msg) {
  if (!Array.isArray(agent._fullHistory)) agent._fullHistory = []
  if (msg && msg.ts === undefined) msg.ts = Date.now()
  agent._fullHistory.push(msg)
  try { agent._recordStore?.append(msg) } catch { /* 尽力面：落盘失败不阻断回合（N-S6） */ }
  const win = agent._historyWindow
  if (win > 0 && agent._fullHistory.length > win) {
    agent._fullHistory.splice(0, agent._fullHistory.length - win)
  }
  agent.history.push(msg)
}

fns.pushRecord:
function pushRecord(agent, record) {
  if (!agent || typeof agent !== "object") return // 载体缺位：零动作（零抛——§6.26 失败面）
  if (!Array.isArray(agent._fullHistory)) agent._fullHistory = []
  // 载体形人读线半提取（先例 = 桌面 `session-io.appendRecord`）：`history` 弃数组承接 ⇒ 机器线零触
  pushReal({ _fullHistory: agent._fullHistory, _recordStore: agent._recordStore, _historyWindow: agent._historyWindow, history: [] }, record)
}

fns.summarizeRunExplorations:
async function summarizeRunExplorations(agent, callbacks, signal, depth = 0, extras) {
  const next = await distillExplorations(agent.history, agent._runStartHistoryLen ?? 0, agent.provider, signal, agent, depth, extras)
  if (!next) return
  agent.history = next
  // The machine line changed shape — the measured token baseline was for the pre-shrink context.
  // Invalidate so the next compaction check re-estimates instead of over-counting stale history.
  agent._lastPromptTokens = null
  agent._usageAtLen = null
  // The compressed machine line must reach the disk: the run's own save already happened,
  // so without this hook the async distill would leave the session un-compressed on exit.
  callbacks.onDistilled?.()
}

fns.classifyPath:
function classifyPath(p, conv) {
  const s = String(p ?? "")
  if (hasCodeSegment(s, conv)) return "code"
  if (TEMP_FILE.test(s)) return "temp"
  if (DOC_FILE.test(s)) return "doc"
  if (hasAuxSegment(s, conv)) return "aux"
  return "code"
}

fns.isAuxPath:
function isAuxPath(p, conv) {
  return classifyPath(p, conv) === "aux"
}

fns.isCodePath:
function isCodePath(p, conv) {
  return classifyPath(p, conv) === "code"
}

fns.isDocPath:
function isDocPath(p, conv) {
  const s = String(p ?? "")
  return DOC_FILE.test(s) && !hasCodeSegment(s, conv)
}

fns.isExcludedRelPath:
function isExcludedRelPath(rel, decl, base = null) {
  const list = decl?.index?.excludePaths
  if (!Array.isArray(list) || list.length === 0) return false
  let s = String(rel ?? "").replace(/\\/g, "/")
  const root = decl?.root
  if (base != null && root) {
    const converted = relative(root, resolve(base, s)).replace(/\\/g, "/")
    if (converted === ".." || converted.startsWith("../") || isAbsolute(converted)) return false
    s = converted
  }
  return list.some((p) => p && (s === p || s.startsWith(`${p}/`)))
}

fns.loadProjectDeclaration:
function loadProjectDeclaration(cwd) {
  const file = manifestFilePath(cwd) // data-file path (single source — manifest.mjs KD-M1-18)
  const hit = _cache.get(file)
  if (hit) return hit
  const root = dirname(file) // project root the manifest belongs to (cwd may be deeper) — the face's anchor
  if (existsSync(join(root, RETIRED_REL_PATH))) warnRetiredCarrier(root)
  let decl = buildDeclaration(null, root) // missing / unusable manifest → the defaults, root still known
  try {
    const r = readManifest(cwd)
    if (r.ok) {
      decl = buildDeclaration(r.manifest, root)
    } else if (r.reason !== "missing") {
      // Usable-file expectation broken (invalid JSON / wrong shape) → defaults, visible.
      console.warn(`[declaration] ${file} is not a usable declaration (${(r.errors ?? []).join("; ") || r.reason}) — falling back to defaults`)
      logEvent("declaration:error", { path: file, err: `invalid: ${(r.errors ?? []).join("; ")}`.slice(0, 200) })
    }
  } catch (e) {
    // Read error (EACCES …) — same visible degradation, never a throw.
    console.warn(`[declaration] ${file} not readable (${e?.message ?? e}) — falling back to defaults`)
    logEvent("declaration:error", { path: file, err: String(e?.message ?? e).slice(0, 200) })
  }
  _cache.set(file, decl)
  return decl
}

fns.codeSearch:
async function codeSearch(memory, query, { limit = 5 } = {}) {
  const ftsQuery = buildFtsQuery(query)
  if (!ftsQuery && !memory.embedder) return []

  // §6.11 读缝归一（单点取名——函数体内一律用归一值）
  const codeOrigin = normalizeOrigin(memory.codeOrigin)
  const ftsOriginFilter = codeOrigin ? `AND c.origin = ?` : ""
  const vecOriginFilter = codeOrigin ? `AND origin = ?` : ""
  const originParams = codeOrigin ? [codeOrigin] : []

  const ftsList = ftsQuery ? memory.db.prepare(`
    SELECT c.rowid, c.path, c.language, c.symbol_name, c.content, c.line_start, c.line_end, bm25(code_chunks_fts) AS rank
    FROM code_chunks_fts JOIN code_chunks c ON c.rowid = code_chunks_fts.rowid
    WHERE code_chunks_fts MATCH ? ${ftsOriginFilter}
    ORDER BY rank LIMIT ?
  `).all(ftsQuery, ...originParams, Math.max(limit * 4, 20)) : []

  if (!memory.embedder) return ftsList.slice(0, limit)

  let ensured
  try { ensured = await ensureEmbeddings(memory) } catch (e) {
    console.error(`[code] embedding ensure failed, falling back to FTS-only: ${e.message}`)
    return ftsList.slice(0, limit)
  }
  if (ensured?.code) { // §6.14 B7 读面零写：模型键失配 ⇒ 本面向量通道降级 FTS-only（一行可见；失效执行归维护口）
    console.warn("[code] embedding model changed — vector channel degraded to FTS-only (rebuild runs at maintenance: sync tail / reindex)")
    return ftsList.slice(0, limit)
  }
  let qvec
  try { [qvec] = await embed(memory.embedder, [query]) } catch (e) {
    console.error(`[code] query embedding failed, falling back to FTS-only: ${e.message}`)
    return ftsList.slice(0, limit)
  }
  // TUI-OOM-ROOTCAUSE（MEMORY.md §10.3）：分块扫描 + 有界 top-K（原全表 .all()——峰值 = 块 + K）
  // TUI 假死批（§6.10 修法 A1/A2）：游标 = PK 去等值过滤前缀列（有 origin 过滤 ⇒ 2 元组；
  // 无过滤 ⇒ 全 PK）；scanVectors = async（让出）。SELECT 须携键列（游标值源）。
  const cursorKey = codeOrigin ? ["path", "line_start"] : ["origin", "path", "line_start"]
  const keyCols = cursorKey.join(", ")
  const top = createTopK(Math.max(limit * 4, 20))
  await scanVectors(memory.db, `SELECT rowid, ${keyCols}, embedding FROM code_chunks WHERE embedding IS NOT NULL ${vecOriginFilter}`, originParams, {
    cursorKey,
    onRow: (r) => top.push({ id: r.rowid, rowid: r.rowid, score: cosine(qvec, fromBlob(r.embedding)) }),
  })
  const vecList = top.list().map((c) => ({ rowid: c.id, score: c.score }))

  const K = 60
  const scores = new Map()
  ftsList.forEach((r, i) => scores.set(r.rowid, (scores.get(r.rowid) ?? 0) + 1 / (K + i + 1)))
  vecList.forEach((r, i) => scores.set(r.rowid, (scores.get(r.rowid) ?? 0) + 1 / (K + i + 1)))

  const fetchChunk = memory.db.prepare(`
    SELECT path, language, symbol_name, content, line_start, line_end FROM code_chunks WHERE rowid = ?
  `)
  const sorted = [...scores.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit)
  return sorted
    .map(([rowid, score]) => {
      const chunk = fetchChunk.get(rowid)
      if (!chunk) return null
      chunk._score = Math.round(score * 100) / 100
      return chunk
    })
    .filter(Boolean)
}

fns.codeSearchTool:
function codeSearchTool(memory) {
  return {
    name: "code_search",
    description: DESC("code_search"), // #15 外置：文本单点 = tool-docs/code_search.md
    parameters: {
      type: "object",
      properties: {
        query: { type: "string", description: "Natural language or code snippet to search for" },
        limit: { type: "number", description: "Max results (default 5)" },
      },
      required: ["query"],
    },
    readonly: true,
    async execute(args) {
      const results = await codeSearch(memory, args.query, { limit: args.limit ?? 5 })
      if (results.length === 0) return "(no matching code)"
      return results.map((r) =>
        `${r.path}${r.symbol_name ? ` :: ${r.symbol_name}` : ""} (L${r.line_start}-L${r.line_end}, relevance ${r._score?.toFixed(2) ?? "?"}):\n${r.content.slice(0, 2000)}`
      ).join("\n\n---\n\n")
    },
  }
}

fns.codeSync:
async function codeSync(memory, dir, { onProgress, yieldFn = yieldTick, nowFn = Date.now, yieldMs = SCAN_YIELD_MS } = {}) {
  const origin = normalizeOrigin(dir) // §6.11 写缝归一（遍历/git I/O 用原样 dir；库面 origin 一律归一值）
  const decl = loadProjectDeclaration(dir)
  const { code: exts } = indexExtensions(dir)
  const { entries, unlisted } = await listProjectFiles(dir, exts)
  const files = [] // { abs, rel, mtimeMs }
  let overSizeSkipped = 0
  for (const { abs, rel } of entries) {
    let st
    try { st = await stat(abs) } catch { continue }
    if (st.size > MAX_CODE_FILE_BYTES) { overSizeSkipped++; continue }
    files.push({ abs, rel, mtimeMs: Math.floor(st.mtimeMs) })
  }
  // §6.14 P2：处理序钉死 = `rel` 字典序（现 walk ∕ git 列序不确定；预算跳过 = 列序后缀）
  files.sort((a, b) => (a.rel < b.rel ? -1 : a.rel > b.rel ? 1 : 0))

  const indexed = new Map(
    memory.db.prepare(`SELECT path, mtime_ms FROM code_chunks WHERE origin = ?`).all(origin).map((r) => [r.path, r.mtime_ms])
  )
  const seen = new Set()

  onProgress?.({ phase: "scan", total: files.length, overSizeSkipped })

  // §6.14 P2 行预算（基准 = 本 origin 库内行数 code+doc，开趟读一次；只停新增——存量行不失效；
  // 跳过 = 不落行 ∕ 不记 mtime ⇒ 下趟重试）。WARN 一行可见（每趟至多一行）+ CAP 起跳过后列文件。
  const budget = createRowBudget(memory, origin, "code", dir)
  const budgetSkipped = []

  let updated = 0, removed = 0, skipped = 0, failed = 0
  const errors = []
  for (let i = 0; i < files.length; i++) {
    const { abs, rel, mtimeMs } = files[i]
    seen.add(rel)

    if (indexed.get(rel) === mtimeMs) {
      skipped++
      continue
    }
    budget.note()
    if (budget.over()) { budgetSkipped.push(rel); continue }

    try {
      const before = rowCountOfPath(memory, "code_chunks", origin, rel)
      const text = await readFile(abs, "utf8")
      const lines = text.split("\n")
      const lang = detectLanguage(abs)
      _upsertCodeFile(memory, origin, rel, lines, lang, mtimeMs)
      budget.add(rowCountOfPath(memory, "code_chunks", origin, rel) - before) // 净增行数——预算与「库内行数」同刻度
      updated++
    } catch (e) {
      failed++
      if (errors.length < 5) errors.push(`${rel}: ${e.message}`)
    }
    await yieldTick()

    if (onProgress && i % 10 === 0) {
      onProgress({ phase: "index", current: i + 1, total: files.length, updated, removed, skipped, failed })
    }
  }

  // §6.14 B6 ∕ M3：收尾 stale 循环（同款让出 + 面① 收尾保护位）——机制单源 = `sync-tail.mjs`
  removed = await sweepStaleRows(memory, { table: "code_chunks", origin, indexed, seen, decl, base: dir, yieldFn, nowFn, yieldMs })

  onProgress?.({ phase: "done", total: files.length, updated, removed, skipped, failed, overSizeSkipped, budgetSkipped: budgetSkipped.length })
  // §6.14 B7 维护口：模型键失配的失效**执行**（读面只判定降级——执行住同步尾；覆盖 /reindex ∕ 桌面 ∕ VSC 构建）
  if (memory.embedder) { try { invalidateStaleEmbeddings(memory) } catch { /* 非阻塞 */ } }
  await markIndexedCommit(memory, dir) // 锚推进 = 同步完成条件（§6.14 M1——原 fire-and-forget 竞态，T12 ∕ T14 判别面需确定性）
  if (unlisted.count > 0) {
    logEvent("index:unlisted", { dir, kind: "code", count: unlisted.count, exts: unlisted.exts.map((e) => e.ext) })
  }
  return { updated, removed, skipped, failed, errors, total: files.length, overSizeSkipped, budgetSkipped, unlistedExts: unlisted }
}

fns.ensureCodeEmbeddings:
function ensureCodeEmbeddings(memory) {
  if (_codeEmbedLock) return _codeEmbedLock
  _codeEmbedLock = _runEnsureCodeEmbeddings(memory).finally(() => { _codeEmbedLock = null })
  return _codeEmbedLock
}

fns.gitSync:
async function gitSync(memory, dir, { onProgress } = {}) {
  const origin = normalizeOrigin(dir) // §6.11 写缝归一（git / 文件 I/O 用原样 dir；库面 origin 一律归一值）
  const decl = loadProjectDeclaration(dir)
  const { execFile: _execFile } = await import("node:child_process")
  const { code: codeExts, doc: docExts } = indexExtensions(dir)
  const gitRun = (args) => new Promise((resolve, reject) => {
    _execFile("git", args, { cwd: dir, encoding: "utf8", timeout: 10000, windowsHide: true }, (err, stdout) => {
      if (err) reject(err); else resolve(stdout)
    })
  })
  const mergeDiff = (text) => text.trim().split("\n").filter(Boolean)

  let head
  try { head = (await gitRun(["rev-parse", "HEAD"])).trim() } catch { return null }

  const stored = memory.db.prepare(`SELECT value FROM meta WHERE key = ?`).get(anchorKey(origin))?.value
  if (!stored) return null

  let diffOut
  try {
    // §6.14 M2：`--relative`——diff 表收在 cwd 子树内且路径为 cwd 相对（与索引 path ∕ `codeSync` 同形；
    // 无它则子目录 origin 下 `join(dir, rel)` 错位：真改动入删除支 ∕ 错内容入库 = 静默陈旧）。
    const committed = mergeDiff(await gitRun(["diff", "--name-only", "--relative", "--diff-filter=ACMRTD", stored, "HEAD"]))
    const dirty = mergeDiff(await gitRun(["diff", "--name-only", "--relative", "--diff-filter=ACMRTD"]))
    const lines = [...new Set([...committed, ...dirty])]
    diffOut = lines
  } catch {
    return null
  }

  if (diffOut.length > DIFF_FULL_SYNC_THRESHOLD) {
    // diff too large, incremental is useless — fall back to full sync and update anchor
    await codeSync(memory, dir, { onProgress })
    const { docSync } = await import("./docs.mjs")
    await docSync(memory, dir, { onProgress })
    return { updated: -1, removed: 0, skipped: 0, failed: 0, errors: [], fallback: true }
  }

  let updated = 0, removed = 0, skipped = 0, failed = 0
  const errors = []
  for (let i = 0; i < diffOut.length; i++) {
    const rel = diffOut[i].replaceAll("\\", "/")
    const abs = join(dir, rel)
    const ext = extensionOf(rel)

    if (isSkippedRelPath(rel) || isExcludedRelPath(rel, decl, dir)) continue

    if (!codeExts.has(ext) && !docExts.has(ext)) { skipped++; continue }

    try {
      const text = await readFile(abs, "utf8")
      const lines = text.split("\n")
      if (codeExts.has(ext)) {
        const lang = detectLanguage(abs)
        let mtimeMs = 0
        try { mtimeMs = Math.floor((await stat(abs)).mtimeMs) } catch { /* new file */ }
        _upsertCodeFile(memory, origin, rel, lines, lang, mtimeMs)
      } else {
        let mtimeMs = 0
        try { mtimeMs = Math.floor((await stat(abs)).mtimeMs) } catch { /* new file */ }
        _upsertDocFile(memory, origin, rel, lines, mtimeMs)
      }
      updated++
    } catch (e) {
      const isDeleted = e.code === "ENOENT"
      if (isDeleted) {
        if (codeExts.has(ext)) memory.db.prepare(`DELETE FROM code_chunks WHERE origin = ? AND path = ?`).run(origin, rel)
        else memory.db.prepare(`DELETE FROM doc_chunks WHERE origin = ? AND path = ?`).run(origin, rel)
        removed++
      } else {
        failed++
        if (errors.length < 5) errors.push(`${rel}: ${e.message}`)
      }
    }
    await yieldTick()
    if (onProgress && i % 5 === 0) {
      onProgress({ phase: "index", current: i + 1, total: diffOut.length, updated, removed, skipped })
    }
  }

  if (failed === 0) {
    memory.db.prepare(`INSERT INTO meta (key, value) VALUES (?, ?)
      ON CONFLICT (key) DO UPDATE SET value = excluded.value`).run(anchorKey(origin), head)
  }

  onProgress?.({ phase: "done", total: diffOut.length, updated, removed, skipped, failed })
  return { updated, removed, skipped, failed, errors }
}

fns.indexExtensions:
function indexExtensions(dir) {
  const conv = loadProjectDeclaration(dir)
  return {
    code: new Set([...CODE_EXTS, ...conv.index.codeExtensions]),
    doc: new Set([...DOC_EXTS, ...conv.index.docExtensions]),
  }
}

fns.listProjectFiles:
async function listProjectFiles(dir, exts, { maxFiles } = {}) {
  const { execFile: _execFile } = await import("node:child_process")
  const { join: joinPath } = await import("node:path")
  const { code, doc } = indexExtensions(dir)
  const decl = loadProjectDeclaration(dir)
  const excluded = (rel) => isExcludedRelPath(rel, decl, dir)
  const tally = createUnlistedTally(new Set([...code, ...doc]))

  const files = []
  const finish = (truncated = false) => ({ entries: files, unlisted: tally.result(), truncated })

  // Git listing when available; a non-git project falls through to the walk.
  let gitTop
  try {
    gitTop = (await new Promise((resolve, reject) => {
      _execFile("git", ["rev-parse", "--show-toplevel"], { cwd: dir, encoding: "utf8", timeout: 5000, windowsHide: true },
        (err, stdout) => { if (err) reject(err); else resolve(stdout.trim()) })
    })).replace(/\\/g, "/")
  } catch {
    // Not a git repo → filesystem walk (FR15: the index must still be usable).
    const walked = await walkProjectFiles(dir, exts, { knownExts: new Set([...code, ...doc]), isExcluded: excluded, ...(maxFiles !== undefined ? { maxFiles } : {}) })
    files.push(...walked.files)
    // The walk's cap must stay visible end-to-end (file-walk.mjs: "never silently
    // dropped") — a capped listing says so in the log, not only in a discarded flag.
    if (walked.truncated) {
      logEvent("index:truncated", { dir, files: walked.files.length, maxFiles: maxFiles ?? MAX_WALK_FILES })
    }
    return { entries: files, unlisted: walked.unlisted, truncated: walked.truncated }
  }

  try {
    const raw = await new Promise((resolve, reject) => {
      _execFile("git", ["ls-files", "--cached", "--others", "--exclude-standard"],
        { cwd: dir, encoding: "utf8", timeout: 15000, windowsHide: true, maxBuffer: 10 * 1024 * 1024 },
        (err, stdout) => { if (err) reject(err); else resolve(stdout) })
    })
    for (const line of raw.trim().split("\n")) {
      const p = line.trim()
      if (!p) continue
      const rel = p.replace(/\\/g, "/")
      if (isSkippedRelPath(rel) || excluded(rel)) continue
      const ext = extensionOf(rel)
      if (!ext || !exts.has(ext)) { tally.note(rel); continue }
      files.push({ abs: joinPath(dir, rel), rel })
    }
  } catch { /* ls-files failed */ }

  return finish()
}

fns.markIndexedCommit:
async function markIndexedCommit(memory, dir) {
  try {
    const { execFile } = await import("node:child_process")
    const origin = normalizeOrigin(dir)
    const head = await new Promise((resolve, reject) => {
      execFile("git", ["rev-parse", "HEAD"], { cwd: dir, encoding: "utf8", timeout: 5000, windowsHide: true }, (err, stdout) => {
        if (err) reject(err); else resolve(stdout)
      })
    })
    memory.db.prepare(`INSERT INTO meta (key, value) VALUES (?, ?)
      ON CONFLICT (key) DO UPDATE SET value = excluded.value`).run(anchorKey(origin), head.trim())
  } catch { /* not a git repo or git unavailable, skip */ }
}

fns.reindexFile:
async function reindexFile(memory, cwd, absPath) {
  const origin = normalizeOrigin(cwd) // §6.11 写缝归一（文件 I/O 用原样 cwd；库面 origin 一律归一值）
  const ext = extensionOf(absPath)
  const rel = relative(cwd, absPath).replaceAll("\\", "/")
  if (rel === ".." || rel.startsWith("../")) return
  if (isSkippedRelPath(rel)) return
  if (isExcludedRelPath(rel, loadProjectDeclaration(cwd), cwd)) return // §6.14 面① 第三起效点（单文件缝零写）
  // Declared extensions count for the single-file path too (union with built-ins).
  const { code: codeExts, doc: docExts } = indexExtensions(cwd)

  // skip oversized files (minified bundles, test fixtures, generated code)
  const maxBytes = codeExts.has(ext) ? MAX_CODE_FILE_BYTES : docExts.has(ext) ? MAX_DOC_FILE_BYTES : 0
  if (maxBytes > 0) {
    try { const st = await stat(absPath); if (st.size > maxBytes) return } catch { /* can't stat, proceed */ }
  }

  let text
  try { text = await readFile(absPath, "utf8") } catch {
    if (codeExts.has(ext)) memory.db.prepare(`DELETE FROM code_chunks WHERE origin = ? AND path = ?`).run(origin, rel)
    else if (docExts.has(ext)) memory.db.prepare(`DELETE FROM doc_chunks WHERE origin = ? AND path = ?`).run(origin, rel)
    return
  }
  const lines = text.split("\n")

  if (codeExts.has(ext)) {
    const lang = detectLanguage(absPath)
    let mtimeMs = 0
    try { mtimeMs = Math.floor((await stat(absPath)).mtimeMs) } catch { /* new file */ }
    _upsertCodeFile(memory, origin, rel, lines, lang, mtimeMs)
  } else if (docExts.has(ext)) {
    let mtimeMs = 0
    try { mtimeMs = Math.floor((await stat(absPath)).mtimeMs) } catch { /* new file */ }
    _upsertDocFile(memory, origin, rel, lines, mtimeMs)
  }
  if (memory.embedder) {
    try { await ensureEmbeddings(memory) } catch { /* embedding failure is non-blocking */ }
  }
}

fns.docSearch:
async function docSearch(memory, query, { limit = 5 } = {}) {
  const ftsQuery = buildFtsQuery(query)
  if (!ftsQuery && !memory.embedder) return []

  // §6.11 读缝归一（单点取名——函数体内一律用归一值）
  const codeOrigin = normalizeOrigin(memory.codeOrigin)
  const ftsOriginFilter = codeOrigin ? `AND d.origin = ?` : ""
  const vecOriginFilter = codeOrigin ? `AND origin = ?` : ""
  const originParams = codeOrigin ? [codeOrigin] : []

  const ftsList = ftsQuery ? memory.db.prepare(`
    SELECT d.rowid, d.path, d.language, d.heading, d.content, d.line_start, d.line_end, bm25(doc_chunks_fts) AS rank
    FROM doc_chunks_fts JOIN doc_chunks d ON d.rowid = doc_chunks_fts.rowid
    WHERE doc_chunks_fts MATCH ? ${ftsOriginFilter}
    ORDER BY rank LIMIT ?
  `).all(ftsQuery, ...originParams, Math.max(limit * 4, 20)) : []

  if (!memory.embedder) return ftsList.slice(0, limit)

  let docEnsured
  try { docEnsured = await ensureDocEmbeddings(memory) } catch (e) {
    console.error(`[docs] embedding ensure failed, falling back to FTS-only: ${e.message}`)
    return ftsList.slice(0, limit)
  }
  if (docEnsured?.mismatch) { // §6.14 B7 读面零写：模型键失配 ⇒ 本面向量通道降级 FTS-only（一行可见；失效执行归维护口）
    console.warn("[docs] embedding model changed — vector channel degraded to FTS-only (rebuild runs at maintenance: sync tail / reindex)")
    return ftsList.slice(0, limit)
  }
  let qvec
  try { [qvec] = await embed(memory.embedder, [query]) } catch (e) {
    console.error(`[docs] query embedding failed, falling back to FTS-only: ${e.message}`)
    return ftsList.slice(0, limit)
  }
  // TUI-OOM-ROOTCAUSE（MEMORY.md §10.3）：分块扫描 + 有界 top-K（原全表 .all()——峰值 = 块 + K）
  // TUI 假死批（§6.10 修法 A1/A2）：游标 = PK 去等值过滤前缀列（有 origin 过滤 ⇒ 2 元组；
  // 无过滤 ⇒ 全 PK）；scanVectors = async（让出）。SELECT 须携键列（游标值源）。
  const cursorKey = codeOrigin ? ["path", "line_start"] : ["origin", "path", "line_start"]
  const keyCols = cursorKey.join(", ")
  const top = createTopK(Math.max(limit * 4, 20))
  await scanVectors(memory.db, `SELECT rowid, ${keyCols}, embedding FROM doc_chunks WHERE embedding IS NOT NULL ${vecOriginFilter}`, originParams, {
    cursorKey,
    onRow: (r) => top.push({ id: r.rowid, rowid: r.rowid, score: cosine(qvec, fromBlob(r.embedding)) }),
  })
  const vecList = top.list().map((c) => ({ rowid: c.id, score: c.score }))

  const K = 60
  const scores = new Map()
  ftsList.forEach((r, i) => scores.set(r.rowid, (scores.get(r.rowid) ?? 0) + 1 / (K + i + 1)))
  vecList.forEach((r, i) => scores.set(r.rowid, (scores.get(r.rowid) ?? 0) + 1 / (K + i + 1)))

  const fetchChunk = memory.db.prepare(`
    SELECT path, language, heading, content, line_start, line_end FROM doc_chunks WHERE rowid = ?
  `)
  const sorted = [...scores.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit)
  return sorted
    .map(([rowid, score]) => {
      const chunk = fetchChunk.get(rowid)
      if (!chunk) return null
      chunk._score = Math.round(score * 100) / 100
      return chunk
    })
    .filter(Boolean)
}

fns.docSearchTool:
function docSearchTool(memory) {
  return {
    name: "doc_search",
    description: DESC("doc_search"), // #15 外置：文本单点 = tool-docs/doc_search.md
    parameters: {
      type: "object",
      properties: {
        query: { type: "string", description: "Natural language search query" },
        limit: { type: "number", description: "Max results (default 5)" },
      },
      required: ["query"],
    },
    readonly: true,
    async execute(args) {
      const results = await docSearch(memory, args.query, { limit: args.limit ?? 5 })
      if (results.length === 0) return "(no matching documentation)"
      return results.map((r) =>
        `${r.path}${r.heading ? ` > ${r.heading}` : ""} (L${r.line_start}-L${r.line_end}, relevance ${r._score?.toFixed(2) ?? "?"}):\n${r.content.slice(0, 2000)}`
      ).join("\n\n---\n\n")
    },
  }
}

fns.docSync:
async function docSync(memory, dir, { onProgress, yieldFn = yieldTick, nowFn = Date.now, yieldMs = SCAN_YIELD_MS } = {}) {
  const origin = normalizeOrigin(dir) // §6.11 写缝归一（目录/git I/O 用原样 dir；库面 origin 一律归一值）
  const decl = loadProjectDeclaration(dir)
  const { entries, unlisted } = await listProjectFiles(dir, indexExtensions(dir).doc)
  const files = [] // { abs, rel, mtimeMs }
  let overSizeSkipped = 0
  for (const { abs, rel } of entries) {
    let st
    try { st = await stat(abs) } catch { continue }
    if (st.size > MAX_DOC_FILE_BYTES) { overSizeSkipped++; continue }
    files.push({ abs, rel, mtimeMs: Math.floor(st.mtimeMs) })
  }
  // §6.14 P2：处理序钉死 = `rel` 字典序（现 walk ∕ git 列序不确定；预算跳过 = 列序后缀）
  files.sort((a, b) => (a.rel < b.rel ? -1 : a.rel > b.rel ? 1 : 0))

  const indexed = new Map(
    memory.db.prepare(`SELECT path, mtime_ms FROM doc_chunks WHERE origin = ?`).all(origin).map((r) => [r.path, r.mtime_ms])
  )
  const seen = new Set()

  onProgress?.({ phase: "scan", total: files.length, overSizeSkipped })

  // §6.14 P2 行预算（单源 = createRowBudget：WARN 一行可见 ∕ CAP 跳过后列——只停新增，存量行不失效）
  const budget = createRowBudget(memory, origin, "doc", dir)
  const budgetSkipped = []

  let updated = 0, removed = 0, skipped = 0, failed = 0
  const errors = []
  for (let i = 0; i < files.length; i++) {
    const { abs, rel, mtimeMs } = files[i]
    seen.add(rel)

    if (indexed.get(rel) === mtimeMs) {
      skipped++
      continue
    }
    budget.note()
    if (budget.over()) { budgetSkipped.push(rel); continue }

    try {
      const before = rowCountOfPath(memory, "doc_chunks", origin, rel)
      const text = await readFile(abs, "utf8")
      const lines = text.split("\n")
      _upsertDocFile(memory, origin, rel, lines, mtimeMs)
      budget.add(rowCountOfPath(memory, "doc_chunks", origin, rel) - before) // 净增行数——与「库内行数」同刻度
      updated++
    } catch (e) {
      failed++
      if (errors.length < 5) errors.push(`${rel}: ${e.message}`)
    }
    await yieldTick()

    if (onProgress && i % 10 === 0) {
      onProgress({ phase: "index", current: i + 1, total: files.length, updated, removed, skipped, failed })
    }
  }

  // §6.14 B6 ∕ M3：收尾 stale 循环（同款让出 + 面① 收尾保护位）——机制单源 = `sync-tail.mjs`
  removed = await sweepStaleRows(memory, { table: "doc_chunks", origin, indexed, seen, decl, base: dir, yieldFn, nowFn, yieldMs })

  onProgress?.({ phase: "done", total: files.length, updated, removed, skipped, failed, overSizeSkipped, budgetSkipped: budgetSkipped.length })
  // §6.14 B7 维护口：模型键失配的失效**执行**（读面只判定降级——执行住同步尾）
  if (memory.embedder) { try { invalidateStaleEmbeddings(memory) } catch { /* 非阻塞 */ } }
  await markIndexedCommit(memory, dir) // 锚推进 = 同步完成条件（§6.14 M1——原 fire-and-forget 竞态）
  if (unlisted.count > 0) {
    logEvent("index:unlisted", { dir, kind: "doc", count: unlisted.count, exts: unlisted.exts.map((e) => e.ext) })
  }
  return { updated, removed, skipped, failed, errors, total: files.length, overSizeSkipped, budgetSkipped, unlistedExts: unlisted }
}

fns.ensureDocEmbeddings:
function ensureDocEmbeddings(memory) {
  if (_docEmbedLock) return _docEmbedLock
  _docEmbedLock = _runEnsureDocEmbeddings(memory).finally(() => { _docEmbedLock = null })
  return _docEmbedLock
}

fns.memoryTools:
function memoryTools(memory, opts = {}) {
  const projectDir = opts.projectDir ? (isAbsolute(opts.projectDir) ? opts.projectDir : join(opts.cwd ?? process.cwd(), opts.projectDir)) : null
  // §6.11：dirs 保持原样（目录 I/O 基准）——归一落在各公共入口内（写缝 syncDir / indexMarkdownFile、
  // 删缝 deleteByUid / matchMemoryRows、读缝 search / fetchEntry）⇒ 逐入口一行，非工具层预归一。
  const dirs = { project: projectDir, team: opts.team?.dir ?? null }
  return [
    {
      name: "memory",
      description: DESC("memory"), // #15 外置：文本单点 = tool-docs/memory.md
      parameters: {
        type: "object",
        properties: {
          action: { type: "string", enum: MEMORY_ACTIONS, description: "Operation to run (required)" },
          layer: { type: "string", enum: MEMORY_LAYERS, description: "The memory layer: personal (private), project (shared via this repo's .thincoder/memory/), team (CLI only). Same concept as the [layer] tag and the id prefix on search/list result rows. put/search/list: optional (put defaults to personal; search/list omit = all layers). single delete: optional (omit = route by id prefix). batch delete/clear: required" },
          type: { type: "string", enum: ["rule", "knowledge", "decision", "pattern"], description: "Entry type: put = what to save; list/delete batch = filter by type" },
          title: { type: "string", description: "put: short title" },
          content: { type: "string", description: "put: full content to remember" },
          tags: { type: "string", description: "put: space-separated tags" },
          query: { type: "string", description: "search: natural-language query" },
          keyword: { type: "string", description: "list/delete batch: filter matching title/content" },
          id: { type: "string", description: "delete single: the entry id from put/search/list output" },
          limit: { type: "number", description: "Max rows: list 50 by default, search 5 by default" },
          confirm: { type: "boolean", description: "delete batch/clear: must be true — without it the tool refuses" },
        },
        required: ["action"],
      },
      readonly: false,
      async execute(args) {
        const action = String(args?.action ?? "")
        if (!MEMORY_ACTIONS.includes(action)) {
          throw new Error(`memory: unknown action "${action}" — expected one of: ${MEMORY_ACTIONS.join("/")}`)
        }
        switch (action) {
          case "search": return execSearch(memory, args)
          case "put": return execPut(memory, args, opts, dirs)
          case "list": return execList(memory, args, dirs)
          case "delete": return execDelete(memory, args, dirs)
          case "clear": return execClear(memory, args)
        }
      },
    },
  ]
}
